// D3 能力域 + D5 客户端矩阵 + D6 性能 + D8 质量（非真云）
import { R, tools, uc, tele, call, SRC, HDK, PKG, flush, summary, __dirname } from './lib.mjs';
import { spawn } from 'node:child_process';
import { join } from 'node:path';
import { existsSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';

// ===== D3 能力域 =====
{ try { const sd = await call('huaweicloud_search_docs', { query: 'ECS', topic: 'all' }); const rs = await call('huaweicloud_retrieve_skill', { name: 'huawei-ecs' }); R('D3-A1', sd?.ok === true && rs?.ok === true, 'skill 检索完整性: search_docs ok=' + sd?.ok + ' (' + (sd?.count || 0) + ' 结果) retrieve_skill ok=' + rs?.ok); } catch (e) { R('D3-A1', false, 'skill 检索异常: ' + e.message.slice(0, 100)); } }
{ try { const lo = await call('huaweicloud_list_operations', { service: 'ECS' }); const ok = !!lo?.service || !!lo?.command; R('D3-B1', ok, 'list_operations 规范名: ' + JSON.stringify(lo).slice(0, 160)); } catch (e) { R('D3-B1', false, 'list_operations 异常: ' + e.message.slice(0, 100)); } }
{ try { const ro = await call('huaweicloud_run_readonly_command', { args: ['VPC', 'ListVpcs', '--cli-region=cn-north-4'] }); R('D3-B3', ro?.ok === true, 'run_readonly 脱敏执行: ok=' + ro?.ok + ' (' + (ro?.stdout || '').slice(0, 80) + ')'); } catch (e) { R('D3-B3', false, 'run_readonly 异常: ' + e.message.slice(0, 100)); } }
{ try { const sample = join(homedir(), 'devkit-test', 'testbot2-Linux-CodeArts CLI', '_runner_tmp', 'sample-react'); const df = await call('huaweicloud_detect_framework', { projectPath: sample }); R('D3-B5', df?.ok === true && !!df?.framework, 'detect_framework 识别: ' + JSON.stringify(df).slice(0, 200)); } catch (e) { R('D3-B5', false, 'detect_framework 异常: ' + e.message.slice(0, 100)); } }
{ const services = ['ECS', 'VPC', 'OBS', 'RDS', 'GaussDB', 'CCE', 'FunctionGraph', 'IAM', 'CTS', 'CES', 'DDS', 'DCS', 'SMN', 'DMS', 'WAF', 'CDN', 'ModelArts', 'DEW', 'CBR', 'EVS', 'EIP', 'ELB']; let okCount = 0; const fails = []; for (const s of services) { try { const lo = await call('huaweicloud_list_operations', { service: s }); if (lo?.command || lo?.service) okCount++; else fails.push(s); } catch (e) { fails.push(s + ':' + e.message.slice(0, 30)); } } R('D3-C4', okCount === services.length, '服务矩阵: ' + okCount + '/' + services.length + ' 服务 list_operations 通过' + (fails.length ? ' FAIL=' + fails.join(',') : '')); }
{ try { const cli = await call('huaweicloud_check_cli', {}); R('D3-C5', cli?.installed === true, '工具冒烟: check_cli installed=' + cli?.installed + ' authenticated=' + cli?.authenticated); } catch (e) { R('D3-C5', false, 'check_cli 异常: ' + e.message.slice(0, 100)); } }
{ try { const sc = await call('huaweicloud_service_catalog', { intent: '帮我查云服务器' }); const hit = (sc.recommendedServices || []).some((s) => s === 'ECS'); R('D3-S1', hit, '场景-只读查 ECS 路由: ' + JSON.stringify(sc.recommendedServices)); } catch (e) { R('D3-S1', false, '只读查 ECS 路由异常: ' + e.message.slice(0, 100)); } }
{ try { const sc = await call('huaweicloud_service_catalog', { intent: '部署一个带 MySQL 数据库的 Web 应用并托管静态资源' }); const svcs = sc.recommendedServices || []; R('D3-S5', svcs.length >= 1, '场景-复合意图分层路由: ' + JSON.stringify(svcs)); } catch (e) { R('D3-S5', false, '复合意图路由异常: ' + e.message.slice(0, 100)); } }
{ try { const ee = await call('huaweicloud_explain_error', { errorCode: 'VPC.0010', message: 'PolicyNotAuthorized' }); const ok = !!ee && (ee.errorCode === 'VPC.0010' || !!ee.suggestions); R('D3-S8', ok, '场景-操作失败后排障指引: ' + JSON.stringify(ee).slice(0, 180)); } catch (e) { R('D3-S8', false, 'explain_error 异常: ' + e.message.slice(0, 100)); } }

// ===== D5 客户端矩阵 =====
{ try { const root = join(homedir(), '.codeartsdoer', 'skills'); const dirs = tools.listSkillDirs(root); R('D5-1', Array.isArray(dirs) && dirs.length > 0, '清单发现加载: listSkillDirs=' + dirs.length + ' 技能目录 (root=' + root + ')'); } catch (e) { R('D5-1', false, '清单发现异常: ' + e.message.slice(0, 100)); } }
{ const tl = tools.TOOL_DEFINITIONS || []; const unique = new Set(tl.map((t) => t.name)).size; const schemasOk = tl.every((t) => t.inputSchema?.type === 'object'); R('D5-3', unique === tl.length && unique >= 40 && schemasOk, '工具全量枚举: ' + unique + ' 工具 schema 无重复 (schema object=' + schemasOk + ')'); }

// ===== D6 性能域 =====
{ try { const t0 = Date.now(); for (let i = 0; i < 5; i++) await call('huaweicloud_search_docs', { query: 'ECS', topic: 'all' }); const avg = (Date.now() - t0) / 5; R('D6-1', avg < 2000, '检索响应延迟: 均值=' + avg + 'ms (<2s)'); } catch (e) { R('D6-1', false, '检索延迟异常: ' + e.message.slice(0, 100)); } }
{ const t0 = Date.now(); let ok = false; const child = spawn(process.execPath, [join(SRC, 'mcp-server.mjs')], { stdio: ['pipe', 'pipe', 'pipe'], env: { ...process.env, HUAWEICLOUD_AGENT_TOOLKIT_MODE: 'local' } }); await new Promise((res) => { child.stdout.once('data', () => { ok = true; res(); }); setTimeout(res, 5000); child.stdin.write('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"p","version":"1"}}}\n'); }); child.kill(); const ms = Date.now() - t0; R('D6-3', ok && ms < 5000, 'MCP 冷启时间: ' + ms + 'ms (服务=' + ok + ')'); }
{ let ok = false; let got = 0; const child = spawn(process.execPath, [join(SRC, 'mcp-server.mjs')], { stdio: ['pipe', 'pipe', 'pipe'], env: { ...process.env, HUAWEICLOUD_AGENT_TOOLKIT_MODE: 'local' } }); const N = 10; let buf = ''; child.stdout.on('data', (d) => { buf += d; }); await new Promise((res) => { child.stdin.write('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"p","version":"1"}}}\n' + Array.from({ length: N }, (_, i) => JSON.stringify({ jsonrpc: '2.0', id: i + 10, method: 'tools/list', params: {} })).join('\n') + '\n'); setTimeout(res, 6000); }); child.kill(); const ids = [...buf.matchAll(/"id":(\d+)/g)].map((m) => +m[1]); const toolIds = ids.filter((i) => i >= 10 && i < 10 + N); got = new Set(toolIds).size; ok = got === N; R('D6-4', ok, '并发调度正确性: 并发 ' + N + ' tools/list 收到 ' + got + ' 个响应'); }
{ let marketClear = false; try { const sm = await import('file://' + join(SRC, 'search-market.mjs')); marketClear = typeof sm.clearMarketCache === 'function'; } catch {} const ok = typeof uc.invalidateUpdateCache === 'function' || marketClear; R('D6-9', ok, '缓存清理三入口: invalidateUpdateCache=' + typeof uc.invalidateUpdateCache + ' clearMarketCache=' + marketClear); }

// ===== D8 质量域 =====
{ try { const ag = readFileSync(join(HDK, 'AGENTS.md'), 'utf8'); const toolsCount = (tools.TOOL_DEFINITIONS || []).length; const m = /(\d+)\s*tools/.exec(ag); R('D8-1', toolsCount > 0, '文档与能力一致: 实际工具=' + toolsCount + ' 文档标注=' + (m ? m[1] + ' tools' : '未显式标注')); } catch (e) { R('D8-1', false, '文档能力一致异常: ' + e.message.slice(0, 100)); } }
{ try { const r = await call('huaweicloud_retrieve_skill', { name: 'huawei-getting-started' }); R('D8-4', r?.ok === true && !!r?.content, '引导步骤可机械执行: getting-started ok=' + r?.ok + ' content=' + !!r?.content); } catch (e) { R('D8-4', false, '引导步骤异常: ' + e.message.slice(0, 100)); } }
{ try { const cn = readFileSync(join(HDK, 'README.zh-CN.md'), 'utf8'); const en = readFileSync(join(HDK, 'README.md'), 'utf8'); const cnH1 = (cn.split('\n').find((l) => l.startsWith('# ')) || '').replace('# ', ''); const enH1 = (en.split('\n').find((l) => l.startsWith('# ')) || '').replace('# ', ''); R('D8-6', !!cnH1 && !!enH1, '中英文文档一致: zhH1=' + cnH1 + ' enH1=' + enH1); } catch (e) { R('D8-6', false, '中英文文档异常: ' + e.message.slice(0, 100)); } }
{ try { const names = ['huaweicloud-core', 'huaweicloud-safety', 'huawei-getting-started', 'huawei-ecs', 'huawei-obs', 'huawei-vpc', 'huawei-iam']; let okCount = 0; const fs = []; for (const n of names) { try { const r = await call('huaweicloud_retrieve_skill', { name: n }); if (r?.ok) okCount++; else fs.push(n); } catch (e) { fs.push(n + ':' + e.message.slice(0, 30)); } } R('D8-7', okCount === names.length, '7 meta/通用技能可机械执行: ' + okCount + '/' + names.length + (fs.length ? ' FAIL=' + fs.join(',') : '')); } catch (e) { R('D8-7', false, '7 技能检索异常: ' + e.message.slice(0, 100)); } }
{ let idStable = false; try { const id1 = tele.generateOrRecoverInstallId(); const id2 = tele.generateOrRecoverInstallId(); idStable = !!id1 && id1 === id2; } catch (e) {} const s = tele.sanitizeValue('AK=AKID1234567890 token=abc123'); const redacted = !/AKID1234567890|abc123/.test(s); R('D8-9', idStable && redacted, '安装 ID 与遥测值脱敏: installId 稳定=' + idStable + ' sanitizeValue 脱敏=' + redacted + ' (out=' + JSON.stringify(s).slice(0, 80) + ')'); }
{ try { const m = await import('file://' + join(SRC, 'mcp-config-merge.mjs')); const ok = typeof m.mergeMcpServersFile === 'function' || typeof m.extractUserDelta === 'function' || typeof m.backupMcpConfig === 'function'; R('D8-10', ok, 'MCP 配置备份与合并: exports=' + Object.keys(m).join(',')); } catch (e) { R('D8-10', false, 'MCP 配置合并异常: ' + e.message.slice(0, 100)); } }

flush();
summary('D3D5D6D8');
process.exit(0);
